#include "elit21/shopify/bulk/StagedUploadManager.h"
namespace elit21::shopify::bulk {StagedUploadManager::StagedUploadManager():platform::BusinessComponent("StagedUploadManager","Shopify staged upload target manager",platform::BusinessComponentSpec{"shopify","staged_upload",{},true,true,4U*1024U*1024U}){}Result<StagedUploadTarget>StagedUploadManager::parseTarget(const Json&p){auto target=p.get("stagedTargets").at(0);if(target.isNull())target=p;StagedUploadTarget out;out.url=target.getString("url");out.resource_url=target.getString("resourceUrl");auto params=target.get("parameters");for(std::size_t i=0;i<params.size();++i){auto v=params.at(i);out.parameters[v.getString("name")]=v.getString("value");}if(!out.valid())return Result<StagedUploadTarget>::failure("Invalid Shopify staged upload target");return Result<StagedUploadTarget>::success(std::move(out));}Json StagedUploadManager::buildInput(const std::string&name,const std::string&mime,std::size_t bytes,const std::string&resource){Json input=Json::object();input.set("filename",name);input.set("mimeType",mime);input.set("resource",resource);input.set("httpMethod","POST");input.set("fileSize",std::to_string(bytes));return input;}platform::OperationResult StagedUploadManager::execute(const platform::OperationContext&context){return executeBusiness(context);}}
